// MARK: - 天机演象 原生国际化多语言管理器 (LocalizationManager)
// 支持：zh-Hans, zh-Hant, en, th, vi, id, ja, ko, auto (跟随系统)

public enum AppLanguage: String, CaseIterable, Identifiable {
    case auto = "auto"
    case zhHans = "zh-Hans"
    case zhHant = "zh-Hant"
    case en = "en"
    case th = "th"
    case vi = "vi"
    case id = "id"
    case ja = "ja"
    case ko = "ko"
    
    public var id: String { self.rawValue }
    
    public var displayName: String {
        switch self {
        case .auto:
            let pref = Locale.preferredLanguages.first ?? "zh-Hans"
            let lower = pref.lowercased()
            if lower.contains("hant") || lower.contains("tw") || lower.contains("hk") || lower.contains("mo") {
                return "跟隨系統"
            } else if lower.starts(with: "zh") {
                return "跟随系统"
            } else {
                return "System Default"
            }
        case .zhHans: return "简体中文"
        case .zhHant: return "繁體中文"
        case .en: return "English"
        case .th: return "ภาษาไทย"
        case .vi: return "Tiếng Việt"
        case .id: return "Bahasa Indonesia"
        case .ja: return "日本語"
        case .ko: return "한국어"
        }
    }
}

/// 支持重复 key 捕获的字典字面量包装容器（防止 Swift 原生 Dictionary 字面量静默覆盖同名 key）
public struct ValidatedTranslationTable: ExpressibleByDictionaryLiteral {
    public let entries: [String: String]
    public let duplicateKeys: [String]
    public let rawEntryCount: Int
    
    public init(dictionaryLiteral elements: (String, String)...) {
        var dict = [String: String](minimumCapacity: elements.count)
        var dupes: [String] = []
        for (key, value) in elements {
            if dict.updateValue(value, forKey: key) != nil {
                dupes.append(key)
            }
        }
        self.entries = dict
        self.duplicateKeys = dupes
        self.rawEntryCount = elements.count
    }
    
    public subscript(key: String) -> String? {
        return entries[key]
    }
}

public class LocalizationManager: ObservableObject {
    public static let shared = LocalizationManager()
    
    /// 主 App 与 Widget Extension 是两个沙盒进程。配置 App Group 后，
    /// 共享容器可让小组件跟随 App 内手动选择的语言；未配置时 suite 数据
    /// 只在本进程可见，自动回退系统语言，行为与旧版一致。
    public static let appGroupID = "group.com.yanxiang.compass"
    public static var sharedDefaults: UserDefaults? {
        UserDefaults(suiteName: appGroupID)
    }

    @Published public var currentSetting: AppLanguage {
        didSet {
            let raw = currentSetting.rawValue
            // standard 始终写，保证旧版本用户偏好与 UI 测试参数不丢。
            UserDefaults.standard.set(raw, forKey: "app_language")
            Self.sharedDefaults?.set(raw, forKey: "app_language")
            updateEffectiveLanguage()
            #if canImport(WidgetKit) && !WIDGET_EXTENSION
            if #available(iOS 14.0, *) {
                WidgetCenter.shared.reloadTimelines(ofKind: "TiandiLuopanAlmanacWidget")
            }
            #endif
        }
    }
    
    @Published public var effectiveLanguage: AppLanguage = .zhHans
    public var currentLanguage: AppLanguage { effectiveLanguage }
    public private(set) var isTranslationTableValid: Bool = true
    public private(set) var translationValidationIssues: [String] = []
    
    private let kAppLanguageKey = "app_language"

    /// Widget 进程每次生成 Timeline 前重读共享偏好。
    /// 未配置 App Group 时读不到值，保持系统语言不变。
    /// 只在扩展进程生效：主 App 的 currentSetting 是权威来源，不应被反向覆盖。
    public func syncFromSharedDefaults() {
        #if WIDGET_EXTENSION
        guard let raw = Self.sharedDefaults?.string(forKey: kAppLanguageKey),
              let setting = AppLanguage(rawValue: raw),
              setting != currentSetting else { return }
        currentSetting = setting
        #endif
    }
    
    private init() {
        // 共享容器优先，旧版 standard 值兜底，避免升级后用户的语言选择被重置。
        var saved = Self.sharedDefaults?.string(forKey: kAppLanguageKey)
            ?? UserDefaults.standard.string(forKey: kAppLanguageKey)
            ?? "auto"
        if let idx = CommandLine.arguments.firstIndex(of: "-appLanguage"), idx + 1 < CommandLine.arguments.count {
            saved = CommandLine.arguments[idx + 1]
        }
        let setting = AppLanguage(rawValue: saved) ?? .auto
        self.currentSetting = setting
        self.effectiveLanguage = LocalizationManager.resolveLanguage(for: setting)
        #if !WIDGET_EXTENSION
        // 首次安装或升级时：若共享容器尚无偏好，同步补写，避免小组件冷启动读不到主 App 语言
        if Self.sharedDefaults?.string(forKey: kAppLanguageKey) != setting.rawValue {
            Self.sharedDefaults?.set(setting.rawValue, forKey: kAppLanguageKey)
        }
        #endif
        // Widget Extension 进程内存上限很低，启动时遍历 8 张全量表做完备性校验
        // 会制造不必要的瞬时峰值。校验用于开发期抓漏译，只在主 App 运行。
        #if WIDGET_EXTENSION
        self.isTranslationTableValid = true
        #else
        self.isTranslationTableValid = validateTranslationTables()
        #endif
    }
    
    /// 启动加载时执行非致命的“重复 key 与全语种并集 key 完备性校验”（避免单条翻译疏漏导致 Debug/TestFlight 崩溃，同时可捕获 zhHans 自身笔误）
    @discardableResult
    public func validateTranslationTables() -> Bool {
        let expectedLanguages = AppLanguage.allCases.filter { $0 != .auto }
        var unionKeys = Set<String>()
        for table in localizedStrings.values {
            unionKeys.formUnion(table.entries.keys)
        }
        var issues: [String] = []
        for lang in expectedLanguages {
            guard let table = localizedStrings[lang] else {
                issues.append("[\(lang.rawValue)] 缺少完整语言字典表")
                continue
            }
            if !table.duplicateKeys.isEmpty {
                issues.append("[\(lang.rawValue)] 存在重复本地化 key: \(table.duplicateKeys)")
            }
            let langKeys = Set(table.entries.keys)
            let missing = unionKeys.subtracting(langKeys).sorted()
            if !missing.isEmpty {
                issues.append("[\(lang.rawValue)] 对比全语种并集缺失 key (\(missing.count) 项): \(missing)")
            }
        }
        self.translationValidationIssues = issues
        let allValid = issues.isEmpty
        self.isTranslationTableValid = allValid
        #if DEBUG
        if !issues.isEmpty {
            for issue in issues {
                print("⚠️ [LocalizationManager] \(issue)")
            }
        }
        #endif
        return allValid
    }
    
    public func setLanguage(_ lang: AppLanguage) {
        currentSetting = lang
    }
    
    public static func resolveLanguage(for setting: AppLanguage) -> AppLanguage {
        if setting == .auto {
            let pref = Locale.preferredLanguages.first ?? "zh-Hans"
            let lower = pref.lowercased()
            if lower.contains("hant") || lower.contains("tw") || lower.contains("hk") || lower.contains("mo") {
                return .zhHant
            } else if lower.starts(with: "zh") {
                return .zhHans
            } else if lower.starts(with: "th") {
                return .th
            } else if lower.starts(with: "vi") {
                return .vi
            } else if lower.starts(with: "id") {
                return .id
            } else if lower.starts(with: "ja") {
                return .ja
            } else if lower.starts(with: "ko") {
                return .ko
            } else {
                return .en
            }
        }
        return setting
    }
    
    private func updateEffectiveLanguage() {
        let resolved = LocalizationManager.resolveLanguage(for: currentSetting)
        if effectiveLanguage != resolved {
            effectiveLanguage = resolved
        }
    }
    
    // MARK: - 字符串本地化快速查询
    /// 记录启动后已报警的缺失 key，避免重复刷屏日志。
    /// t() 会被主线程 UI 与后台长卷渲染同时调用，Set 非线程安全，需加锁保护。
    private let missingKeysLock = NSLock()
    private var loggedMissingKeys: Set<String> = []

    public func t(_ key: String) -> String {
        if let value = localizedStrings[effectiveLanguage]?[key] {
            return value
        }
        if let zh = localizedStrings[.zhHans]?[key] {
            return zh
        }
        // 漏译兜底：仍返回原始 key（不崩溃），但每个缺失 key 仅记录一次，
        // 便于在设备控制台 / 崩溃上报中捕获，后续补全翻译。
        missingKeysLock.lock()
        let shouldLog = loggedMissingKeys.insert(key).inserted
        missingKeysLock.unlock()
        if shouldLog {
            NSLog("[i18n] missing key: \(key) (lang=\(effectiveLanguage))")
        }
        return key
    }
    
